   129	/**
   130	 * gnutls_pkcs12_bag_get_data:
   131	 * @bag: The bag
   132	 * @indx: The element of the bag to get the data from
   133	 * @data: where the bag's data will be. Should be treated as constant.
   134	 *
   135	 * This function will return the bag's data. The data is a constant
   136	 * that is stored into the bag.  Should not be accessed after the bag
   137	 * is deleted.
   138	 *
   139	 * Returns: On success, %GNUTLS_E_SUCCESS (0) is returned, otherwise a
   140	 *   negative error value.
   141	 **/
   142	int
   143	gnutls_pkcs12_bag_get_data(gnutls_pkcs12_bag_t bag, unsigned indx,
   144	                           gnutls_datum_t * data)
   145	{
   146	        if (bag == NULL) {
   147	                gnutls_assert();
   148	                return GNUTLS_E_INVALID_REQUEST;
   149	        }
   150	
   151	        if (indx >= bag->bag_elements)
   152	                return GNUTLS_E_REQUESTED_DATA_NOT_AVAILABLE;
   153	
   154	        data->data = bag->element[indx].data.data;
   155	        data->size = bag->element[indx].data.size;
   156	
   157	        return 0;
   158	}
