   265	int
   266	_pkcs12_encode_crt_bag(gnutls_pkcs12_bag_type_t type,
   267	                       const gnutls_datum_t * raw, gnutls_datum_t * out)
   268	{
   269	        int ret;
   270	        ASN1_TYPE c2 = ASN1_TYPE_EMPTY;
   271	
   272	        switch (type) {
   273	        case GNUTLS_BAG_CERTIFICATE:
   274	                if ((ret = asn1_create_element(_gnutls_get_pkix(),
   275	                                               "PKIX1.pkcs-12-CertBag",
   276	                                               &c2)) != ASN1_SUCCESS) {
   277	                        gnutls_assert();
   278	                        ret = _gnutls_asn2err(ret);
   279	                        goto cleanup;
   280	                }
   281	
   282	                ret = asn1_write_value(c2, "certId", X509_CERT_OID, 1);
   283	                if (ret != ASN1_SUCCESS) {
   284	                        gnutls_assert();
   285	                        ret = _gnutls_asn2err(ret);
   286	                        goto cleanup;
   287	                }
   288	
   289	                ret =
   290	                    _gnutls_x509_write_string(c2, "certValue", raw,
   291	                                              ASN1_ETYPE_OCTET_STRING);
   292	                if (ret < 0) {
   293	                        gnutls_assert();
   294	                        goto cleanup;
   295	                }
   296	                break;
   297	
   298	        case GNUTLS_BAG_CRL:
   299	                if ((ret = asn1_create_element(_gnutls_get_pkix(),
   300	                                               "PKIX1.pkcs-12-CRLBag",
   301	                                               &c2)) != ASN1_SUCCESS) {
   302	                        gnutls_assert();
   303	                        ret = _gnutls_asn2err(ret);
   304	                        goto cleanup;
   305	                }
   306	
   307	                ret = asn1_write_value(c2, "crlId", X509_CRL_OID, 1);
   308	                if (ret != ASN1_SUCCESS) {
   309	                        gnutls_assert();
   310	                        ret = _gnutls_asn2err(ret);
   311	                        goto cleanup;
   312	                }
   313	
   314	                ret =
   315	                    _gnutls_x509_write_string(c2, "crlValue", raw,
   316	                                              ASN1_ETYPE_OCTET_STRING);
   317	                if (ret < 0) {
   318	                        gnutls_assert();
   319	                        goto cleanup;
   320	                }
   321	                break;
   322	
   323	        case GNUTLS_BAG_SECRET:
   324	                if ((ret = asn1_create_element(_gnutls_get_pkix(),
   325	                                               "PKIX1.pkcs-12-SecretBag",
   326	                                               &c2)) != ASN1_SUCCESS) {
   327	                        gnutls_assert();
   328	                        ret = _gnutls_asn2err(ret);
   329	                        goto cleanup;
   330	                }
   331	
   332	                ret =
   333	                    asn1_write_value(c2, "secretTypeId", RANDOM_NONCE_OID,
   334	                                     1);
   335	                if (ret != ASN1_SUCCESS) {
   336	                        gnutls_assert();
   337	                        ret = _gnutls_asn2err(ret);
   338	                        goto cleanup;
   339	                }
   340	
   341	                ret =
   342	                    _gnutls_x509_write_string(c2, "secretValue", raw,
   343	                                              ASN1_ETYPE_OCTET_STRING);
   344	                if (ret < 0) {
   345	                        gnutls_assert();
   346	                        goto cleanup;
   347	                }
   348	                break;
   349	
   350	        default:
   351	                gnutls_assert();
   352	                asn1_delete_structure(&c2);
   353	                return GNUTLS_E_UNIMPLEMENTED_FEATURE;
   354	        }
   355	
   356	        ret = _gnutls_x509_der_encode(c2, "", out, 0);
   357	
   358	        if (ret < 0) {
   359	                gnutls_assert();
   360	                goto cleanup;
   361	        }
   362	
   363	        asn1_delete_structure(&c2);
   364	
   365	        return 0;
   366	
   367	
   368	      cleanup:
   369	
   370	        asn1_delete_structure(&c2);
   371	        return ret;
   372	}
