   505	/**
   506	 * gnutls_pkcs12_bag_set_key_id:
   507	 * @bag: The bag
   508	 * @indx: The bag's element to add the id
   509	 * @id: the ID
   510	 *
   511	 * This function will add the given key ID, to the specified, by the
   512	 * index, bag element. The key ID will be encoded as a 'Local key
   513	 * identifier' bag attribute, which is usually used to distinguish
   514	 * the local private key and the certificate pair.
   515	 *
   516	 * Returns: On success, %GNUTLS_E_SUCCESS (0) is returned, otherwise a
   517	 *   negative error value. or a negative error code on error.
   518	 **/
   519	int
   520	gnutls_pkcs12_bag_set_key_id(gnutls_pkcs12_bag_t bag, unsigned indx,
   521	                             const gnutls_datum_t * id)
   522	{
   523	        int ret;
   524	
   525	
   526	        if (bag == NULL) {
   527	                gnutls_assert();
   528	                return GNUTLS_E_INVALID_REQUEST;
   529	        }
   530	
   531	        if (indx > bag->bag_elements - 1) {
   532	                gnutls_assert();
   533	                return GNUTLS_E_INVALID_REQUEST;
   534	        }
   535	
   536	        ret = _gnutls_set_datum(&bag->element[indx].local_key_id,
   537	                                id->data, id->size);
   538	
   539	        if (ret < 0) {
   540	                gnutls_assert();
   541	                return ret;
   542	        }
   543	
   544	        return 0;
   545	}
